from flask import Flask
from redis import Redis

app = Flask(__name__)
redis = Redis(host="127.0.0.1", port=6379, socket_connect_timeout=3, socket_timeout=3)

@app.route("/")
def hello():
    counter = redis.incr("hits")
    return "This webpage has been viewed " + str(counter) + " time(s)"

@app.route("/healthz")
def health():
    redis.ping()
    return "ok"

import os
import signal
import subprocess
import time
from redis import Redis

os.makedirs("/data", exist_ok=True)
children = []
def stop(signum=None, frame=None):
    for child in reversed(children):
        if child.poll() is None:
            child.terminate()
    for child in reversed(children):
        try:
            child.wait(timeout=10)
        except subprocess.TimeoutExpired:
            child.kill()
    raise SystemExit(0 if signum else 1)

signal.signal(signal.SIGTERM, stop)
signal.signal(signal.SIGINT, stop)
children.append(subprocess.Popen(["redis-server", "--bind", "127.0.0.1", "--port", "6379", "--dir", "/data", "--appendonly", "yes", "--appendfsync", "everysec"]))
client = Redis(host="127.0.0.1", socket_connect_timeout=1, socket_timeout=1)
for attempt in range(100):
    if children[0].poll() is not None:
        stop()
    try:
        client.ping()
        break
    except Exception:
        time.sleep(0.1)
else:
    stop()
children.append(subprocess.Popen(["gunicorn", "--bind", "0.0.0.0:8000", "--workers", "2", "--access-logfile", "-", "--error-logfile", "-", "app:app"]))
while all(child.poll() is None for child in children):
    time.sleep(0.5)
stop()

